import {randomUUID} from 'node:crypto';
import {preparePilot,type PilotWorker} from '../../scripts/credit-pilot/setup.js';
import {CEO_CAPABILITIES,RESEARCH_CAPABILITIES,COMPANY_CEILING} from '../../src/domain/model.js';
import type {RuntimeAdapter,RuntimeInput} from '../../src/runtime/adapter.js';
export function pilotFixture(){
 const roster:PilotWorker[]=[{worker_id:'worker_fixture_atlas',principal_id:'principal_fixture_atlas',display_name:'Fixture Atlas',title:'CEO',role:'ceo',manager_worker_id:null,lifecycle:'persistent',runtime_type:'codex-app-server',enabled:1,principal_enabled:1,capability_profile:[...CEO_CAPABILITIES],delegatable_capabilities:[...COMPANY_CEILING]},{worker_id:'worker_fixture_scout',principal_id:'principal_fixture_scout',display_name:'Fixture Scout',title:'Researcher',role:'researcher',manager_worker_id:'worker_fixture_atlas',lifecycle:'persistent',runtime_type:'codex-app-server',enabled:1,principal_enabled:1,capability_profile:[...RESEARCH_CAPABILITIES],delegatable_capabilities:[]}];
 const f=preparePilot(roster,'test-model',process.cwd());
 const adapter:RuntimeAdapter={type:'codex-app-server',supportsInterrupt:true,run:async()=>{throw Error('No ordinary fallback');},runSubscriptionInvestment:async()=>({status:'completed',settled:true})};f.company.investmentTeam.runtime=adapter;
 f.company.creditPilot.approve(f.manifest.scopeId,'test-model',new Date().toISOString());
 f.company.discussions.control({group_id:f.group.group_id,action:'start',receipt_key:randomUUID()});
 const queued=()=>f.store.all<{request_id:string;target_worker_id:string;kind:string}>("SELECT r.request_id,r.target_worker_id,t.kind FROM conversation_requests r JOIN discussion_turns t USING(request_id) WHERE r.status='queued' ORDER BY r.rowid");
 const release=()=>{f.company.discussions.progress();const r=queued()[0]!;f.company.creditPilot.release(r.request_id,f.company.creditPilot.get()!.execution_id);return r;};
 const claim=()=>{release();const c=f.company.claimWorkNext();if(c?.origin!=='conversation')throw Error('Pilot claim missing');return c;};
 const input=(c:ReturnType<typeof claim>):RuntimeInput=>({mode:'conversation',worker:c.worker,request:c.request,execution:c.execution,binding:f.company.conversations.binding(c.context),context:f.company.conversations.context(c.context),tools:f.company.conversations.tools(c.context),localDeadline:f.company.investmentActivity.deadline(c.execution.execution_id)!,prepareBinding:b=>f.company.conversations.prepareBinding(c.context,b),bind:b=>{f.company.conversations.prepareBinding(c.context,b);f.company.conversations.activateBinding(c.context);},configured:cfg=>f.company.recordRuntimeConfig(c.context,cfg),callTool:(id,name,args,signal)=>f.company.conversations.callTool(c.context,id,name,args,signal),event:(type,detail)=>f.company.conversations.event(c.context,type,detail),usage:o=>{f.company.aiUsage.observe(c.execution.execution_id,o);if(o.kind==='turn')f.company.investmentActivity.turn(c.execution.execution_id,o.turnId);},admitSubscription:i=>f.company.investmentActivity.admit(c.context,i)});
 const complete=(c:ReturnType<typeof claim>)=>{const i=input(c),threadId=i.binding?.runtime_reference??'fixture-'+c.execution.session_id,turnId=randomUUID();i.bind({worker_id:c.worker.worker_id,runtime_type:'codex-app-server',runtime_reference:threadId,workspace_path:c.worker.workspace_path,created_at:new Date().toISOString()});i.configured({model:'test-model',reasoning_effort:'low',runtime_version:'fixture',runtime_adapter:'codex-app-server',execution_priority:'normal'});i.usage!({kind:'start',identity:{threadId,model:'test-model',provider:'openai',serviceTier:'standard',freshThread:!i.binding}});i.admitSubscription!({threadId,model:'test-model',accountFingerprint:'a'.repeat(64),eligibility:{authMode:'chatgpt',planType:'pro',paidCredits:'existing_approved',ordinaryUsageAllowed:false,creditUsageAllowed:true,provider:'openai'}});i.usage!({kind:'turn',threadId,turnId});i.usage!({kind:'response',threadId,turnId,responseId:randomUUID(),usage:{inputTokens:100,cachedInputTokens:10,cacheWriteInputTokens:0,outputTokens:20,reasoningOutputTokens:5,totalTokens:120}});
 const kind=f.company.discussions.turn(c.request.request_id)!.kind;if(kind==='facilitate'){const prior=f.store.get<{message_id:string}>('SELECT c.message_id FROM discussion_contributions c JOIN conversation_messages m USING(message_id) WHERE c.group_id=? AND m.worker_id IS NOT NULL ORDER BY c.rowid LIMIT 1',f.group.group_id)!;f.company.conversations.callTool(c.context,randomUUID(),'read_group_record',{record_id:prior.message_id,offset:0});f.company.conversations.callTool(c.context,randomUUID(),'facilitate_discussion',{body:'Deterministic fixture discussion decision.',action:'discuss',turns:[{worker_id:f.roster[1]!.worker_id,prompt:'Inspect prior reasoning',contribution_ids:[prior.message_id],evidence_ids:[]}]});}else {const prior=kind==='response'?f.store.get<{message_id:string}>('SELECT c.message_id FROM discussion_contributions c JOIN conversation_messages m USING(message_id) WHERE c.group_id=? AND m.worker_id IS NOT NULL ORDER BY c.rowid LIMIT 1',f.group.group_id):undefined;if(prior)f.company.conversations.callTool(c.context,randomUUID(),'read_group_record',{record_id:prior.message_id,offset:0});f.company.conversations.callTool(c.context,randomUUID(),'submit_contribution',{body:'Deterministic fixture contribution, not real employee dialogue.',contribution_ids:prior?[prior.message_id]:[],evidence_ids:[],questions:[],answers:[]});}f.company.finish(c.execution.execution_id,{status:'completed',settled:true,summary:'Fixture completion'});};
 return {...f,adapter,queued,release,claim,input,complete};
}
